package net.officefloor.hq.app.claim;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.RequestBody;

/** Reads the body: a move names the person the claim moves to. */
public class ValidateReassign {
    public void validate(@RequestBody ReassignRequest request, Out<ReassignRequest> body)
            throws InvalidClaimStatusException {
        if (request == null || request.personId() == null) {
            throw new InvalidClaimStatusException("A move needs the person the claim moves to");
        }
        body.set(new ReassignRequest(request.personId(), request.by() == null ? "" : request.by().trim()));
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.person.Person;
import net.officefloor.hq.app.person.PersonRepository;
import net.officefloor.hq.app.role.RoleRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Checks a move of a claim to another person on the sheet. Only a role the sheet's reassign permission allows (a steward while it is blank) moves a claim, and only a DRAFT, OPEN or
 * PENDING one: a SETTLED or VOID claim stays. A claim whose due-by falls inside a closed period, a correction (it belongs with the
 * claim it corrects), a move to the claim's own person, to a person not on the sheet, or to one retired before the
 * claim's date, is refused.
 */
public class ApplyReassign {
    public void apply(@Val Claim claim, @Val ReassignRequest request, PersonRepository people, RoleRepository roles,
            SettingRepository settings,             PeriodRepository periods, Out<ClaimReassignment> reassignment) throws InvalidClaimStatusException {
        reassignment.set(check(claim, request, people, roles, settings, periods, false));
    }

    /** The checks of a move; {@code sameAllowed} lets the claim's own person be named (a bulk move keeps it there, listed
     *  as its newest). */
    static ClaimReassignment check(Claim claim, ReassignRequest request, PersonRepository people, RoleRepository roles,
            SettingRepository settings, PeriodRepository periods, boolean sameAllowed) throws InvalidClaimStatusException {
        if (!settings.permits(claim.sheetId(), "reassign", roles.roleOf(claim.sheetId(), request.by()))) {
            throw new InvalidClaimStatusException("The sheet's permission does not let this user move a claim");
        }
        if (claim.status() != ClaimStatus.DRAFT && claim.status() != ClaimStatus.OPEN
                && claim.status() != ClaimStatus.PENDING) {
            throw new InvalidClaimStatusException("A " + claim.status() + " claim cannot move");
        }
        if (claim.corrects() != null) {
            throw new InvalidClaimStatusException("A correction stays with the claim it corrects");
        }
        if (periods.closedOn(claim.sheetId(), claim.dueBy())) {
            throw new InvalidClaimStatusException("The claim's due-by is inside a closed period");
        }
        Person from = people.find(claim.sheetId(), claim.personId());
        Person to = people.find(claim.sheetId(), request.personId());
        if (from == null || to == null || (!sameAllowed && to.id() == from.id())) {
            throw new InvalidClaimStatusException("The claim must move to another person on the sheet");
        }
        if (!to.mayClaimOn(claim.date())) {
            throw new InvalidClaimStatusException("The claim's date is after " + to.name() + "'s retirement");
        }
        return new ClaimReassignment(from, to, request.by());
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.period.PeriodRepository;
import net.officefloor.hq.app.setting.SettingRepository;
import net.officefloor.hq.app.sheet.SheetRepository;
import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/**
 * Stores the move: the claim keeps its date and, when it has a number, receives the next one in the sequence it would
 * be numbered in now (see ClaimNumbering; its old number is never used again — a draft gets none), loses any figure a statement bound it to (its due is live
 * again until its new person's next statement) and is listed as its new person's newest claim. A change another user
 * made first (the claim moved or its status changed) is refused.
 */
public class SaveReassign {
    public void save(@Val Claim claim, @Val ClaimReassignment reassignment, ClaimRepository claims,
            PeriodRepository periods, SettingRepository settings, SheetRepository sheets, Out<Claim> saved)
            throws InvalidClaimStatusException {
        if (!claims.reassign(claim, reassignment.from().id(), reassignment.to().id())) {
            throw new InvalidClaimStatusException("The claim was changed by someone else");
        }
        Claim moved = claims.find(claim.sheetId(), claim.id());
        if (moved.number() != null) {
            claims.renumber(moved, ClaimNumbering.next(moved, claims, periods, settings, sheets));
            moved = claims.find(claim.sheetId(), claim.id());
        }
        saved.set(moved);
    }
}
package net.officefloor.hq.app.claim;

import net.officefloor.hq.app.Audit;
import net.officefloor.hq.app.rollup.Rollup;
import net.officefloor.hq.app.rollup.RollupBefore;
import net.officefloor.plugin.variable.Val;

/** Writes CLAIM_REASSIGNED to the audit file once the move is stored, naming the claim as every claim line does (with
 * its new person, and number=<number> when it has one), ending from=<old name> to=<new name>. Then writes the figures
 * the move moved (see Rollup). */
public class RecordClaimReassigned {
    public void record(@Val Claim claim, @Val ClaimReassignment reassignment, @Val RollupBefore before, Rollup rollup,
            Audit audit) {
        audit.record("CLAIM_REASSIGNED sheet=" + claim.sheetId() + " by=" + reassignment.by() + " person="
                + reassignment.to().name() + " amount=" + claim.amount().toPlainString() + " date=" + claim.date()
                + (claim.number() == null ? "" : " number=" + claim.number()) + " from=" + reassignment.from().name()
                + " to=" + reassignment.to().name());
        rollup.record(claim.sheetId(), reassignment.by(), before);
    }
}
