/** Reads the body: the alias (kept without its outer spaces) and the signed-in user are required. */
public class ValidateAlias {
    public void validate(@RequestBody AliasRequest request, Out<AliasValues> values) throws InvalidPersonException {
        String alias = request == null || request.alias() == null ? "" : request.alias().trim();
        if (alias.isEmpty()) {
            throw new InvalidPersonException("An alias is required");
        }
        String by = request.by() == null ? "" : request.by().trim();
        if (by.isEmpty()) {
            throw new InvalidPersonException("The user adding the alias is required");
        }
        values.set(new AliasValues(alias, by));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import net.officefloor.plugin.variable.Val;

/** Gives the person the alias; one equal to any name or alias on the sheet (case ignored) is a 409. Publishes the person
 *  as stored, with their aliases. */
public class AddAlias {
    public void add(@Val Person person, @Val AliasValues values, PersonRepository people, Out<Person> changed)
            throws DuplicatePersonNameException {
        people.addAlias(person.sheetId(), person.id(), values.alias());
        changed.set(people.find(person.sheetId(), person.id()));
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.hq.app.Audit;
import net.officefloor.plugin.variable.Val;

/** Writes PERSON_ALIAS_ADDED to the audit file once the alias is stored. */
public class RecordAliasAdded {
    public void record(@Val Person person, @Val AliasValues values, Audit audit) {
        audit.record("PERSON_ALIAS_ADDED sheet=" + person.sheetId() + " by=" + values.by() + " name=" + person.name()
                + " alias=" + values.alias());
    }
}
package net.officefloor.hq.app.person;

import net.officefloor.plugin.variable.Out;
import org.springframework.web.bind.annotation.PathVariable;

/** Loads a person of the sheet by id; one not on the sheet is a 404. */
public class LoadPerson {
    public void load(@PathVariable("sheetId") String sheetId, @PathVariable("personId") String personId,
            PersonRepository people, Out<Person> person) throws PersonNotFoundException {
        Person found;
        try {
            found = people.find(sheetId.trim(), Long.parseLong(personId.trim()));
        } catch (NumberFormatException e) {
            found = null;
        }
        if (found == null) {
            throw new PersonNotFoundException("No person " + personId);
        }
        person.set(found);
    }
}
package net.officefloor.hq.app.person;

/** A person's values that cannot be kept: an empty name, or a grade other than A, B or C. */
public class InvalidPersonException extends Exception {
    public InvalidPersonException(String message) {
        super(message);
    }
}
